        $out->{'atomic_commit'} = $this->toAtomicCommit();
        $out->{'atomic_noexcept'} = $this->toAtomicNoexcept();
        $out->{'auto'} = $this->toAuto();
        $out->{'await'} = $this->toAwait();
        $out->{'base'} = $this->toBase();
        $out->{'bitand'} = $this->toBitand();
        $out->{'bitor'} = $this->toBitor();
